"use client"

import { RouteError } from "@/components/route-error"

export default function Error({ error, reset }: { error: Error & { digest?: string }; reset: () => void }) {
  return <RouteError error={error} reset={reset} />
}

import type { Metadata } from "next"
import { profileScopeAttributes } from "@/components/profile-scope"

export const metadata: Metadata = {
  title: "증권 마켓 홈 · doksam-ui 템플릿",
  description:
    "service 프로필(Ocean · Noto Sans KR)을 적용한 증권사 마켓 홈 템플릿 — 시장 지표·실시간 랭킹 스크리너·종목 상세·관심종목(가상 누리증권).",
}

/**
 * 증권 마켓 홈 템플릿(#41) 레이아웃 — profiles/index.ts 의 "service" 프로필
 * (theme: ocean, font: noto-sans-kr, defaultMode: light)을 이 서브트리에만
 * 컨테이너 스코프로 강제한다(profile-preview-kit 패턴).
 */
export default function BrokerageTemplateLayout({ children }: Readonly<{ children: React.ReactNode }>) {
  return (
    <div
      {...profileScopeAttributes("service")}
      className="flex min-h-[calc(100vh-4rem)] flex-col rounded-xl border border-border bg-background font-sans text-foreground"
    >
      {children}
    </div>
  )
}

import { RouteLoading } from "@/components/route-loading"

export default function Loading() {
  return <RouteLoading />
}

import { CalendarBlankIcon, ClockIcon } from "@phosphor-icons/react/dist/ssr"

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { KEY_SCHEDULE, type ScheduleItem } from "@/app/templates/brokerage/_data/schedule"

const IMPORTANCE_LABEL: Record<ScheduleItem["importance"], string> = {
  high: "중요",
  medium: "보통",
  low: "참고",
}

const IMPORTANCE_VARIANT: Record<ScheduleItem["importance"], "destructive" | "secondary" | "outline"> = {
  high: "destructive",
  medium: "secondary",
  low: "outline",
}

function ScheduleRow({ item }: Readonly<{ item: ScheduleItem }>) {
  return (
    <li className="flex items-center gap-3 py-2">
      <div className="flex w-20 shrink-0 flex-col text-xs text-muted-foreground tabular-nums">
        <span className="flex items-center gap-1">
          <CalendarBlankIcon size={11} />
          {item.date}
        </span>
        <span className="flex items-center gap-1">
          <ClockIcon size={11} />
          {item.time}
        </span>
      </div>

      <div className="flex min-w-0 flex-1 flex-col gap-0.5">
        <div className="flex items-center gap-1.5">
          <Badge variant="outline" className="text-[0.65rem]">
            {item.country}
          </Badge>
          <span className="truncate text-sm font-medium text-foreground">{item.title}</span>
        </div>
        {(item.consensus ?? item.previous) && (
          <span className="text-xs text-muted-foreground">
            {item.consensus && <>예상 {item.consensus}</>}
            {item.consensus && item.previous && " · "}
            {item.previous && <>이전 {item.previous}</>}
          </span>
        )}
      </div>

      <Badge variant={IMPORTANCE_VARIANT[item.importance]} className="shrink-0">
        {IMPORTANCE_LABEL[item.importance]}
      </Badge>
    </li>
  )
}

/** 주요 일정 카드(#41-A) — 경제지표 발표 등 다가오는 이벤트를 시간순으로 나열한다. */
export function KeySchedule() {
  return (
    <Card>
      <CardHeader>
        <CardTitle>주요 일정</CardTitle>
      </CardHeader>
      <CardContent>
        <ul className="flex flex-col divide-y divide-border">
          {KEY_SCHEDULE.map((item) => (
            <ScheduleRow key={item.id} item={item} />
          ))}
        </ul>
      </CardContent>
    </Card>
  )
}

import { TrendDownIcon, TrendUpIcon } from "@phosphor-icons/react/dist/ssr"

import { Card, CardContent } from "@/components/ui/card"
import { Sparkline } from "@/components/patterns/dataviz/sparkline"
import { rateColor, rateText } from "@/lib/finance/rate"
import { MARKET_INDICES, type MarketIndex } from "@/app/templates/brokerage/_data/market"

/** 100만 이상(비트코인 등)은 정수로, 그 외는 소수 둘째 자리까지 표기한다. */
function formatValue(item: MarketIndex): string {
  const isLarge = item.value >= 1_000_000
  return `${item.value.toLocaleString(undefined, { maximumFractionDigits: isLarge ? 0 : 2 })}${item.unit}`
}

function MarketIndexCard({ item }: Readonly<{ item: MarketIndex }>) {
  const colorClass = rateColor(item.changePercent)
  const Icon = item.icon

  return (
    <Card size="sm" className="min-w-0">
      <CardContent className="flex flex-col gap-2">
        <div className="flex items-center justify-between gap-2">
          <span className="flex items-center gap-1.5 text-xs font-medium text-muted-foreground">
            <Icon size={13} />
            {item.label}
          </span>
          <span className="rounded-full bg-muted px-1.5 py-0.5 text-[0.65rem] font-medium text-muted-foreground">
            {item.group}
          </span>
        </div>

        <div className="flex items-baseline justify-between gap-2">
          <span className="truncate text-lg font-semibold tabular-nums">{formatValue(item)}</span>
          <span className={`flex shrink-0 items-center gap-0.5 text-xs font-medium tabular-nums ${colorClass}`}>
            {item.changePercent > 0 && <TrendUpIcon size={11} weight="bold" />}
            {item.changePercent < 0 && <TrendDownIcon size={11} weight="bold" />}
            {rateText(item.changePercent)}%
          </span>
        </div>

        <Sparkline values={item.trend} height={28} className={colorClass} />
      </CardContent>
    </Card>
  )
}

/**
 * 시장 지표 스트립(#41-A) — 코스피·코스닥·나스닥·S&P500·VIX·달러환율·비트코인·
 * 국제금 등 주요 지표를 미니 스파크라인 + 현재값 + 등락률 카드로 그리드 배열한다.
 * 등락 색은 한국식 관례(상승=적=gain, 하락=청=loss) 시맨틱 토큰만 사용한다.
 */
export function MarketStrip() {
  return (
    <section aria-label="시장 지표" className="flex flex-col gap-2">
      <h2 className="text-sm font-semibold text-foreground">시장 지표</h2>
      <div className="grid grid-cols-2 gap-2 sm:grid-cols-3 md:grid-cols-4 xl:grid-cols-8">
        {MARKET_INDICES.map((item) => (
          <MarketIndexCard key={item.id} item={item} />
        ))}
      </div>
    </section>
  )
}

import { TrendDownIcon, TrendUpIcon } from "@phosphor-icons/react/dist/ssr"

import { rateColor, rateText } from "@/lib/finance/rate"
import { TICKER_ITEMS, type TickerItem } from "@/app/templates/brokerage/_data/market"

function TickerEntry({ item }: Readonly<{ item: TickerItem }>) {
  const colorClass = rateColor(item.changePercent)

  return (
    <span className="flex shrink-0 items-center gap-2 px-4 text-xs">
      <span className="font-medium text-foreground">{item.label}</span>
      <span className="tabular-nums text-muted-foreground">
        {item.value.toLocaleString(undefined, { maximumFractionDigits: item.value >= 1_000_000 ? 0 : 2 })}
        {item.unit}
      </span>
      <span className={`flex items-center gap-0.5 font-medium tabular-nums ${colorClass}`}>
        {item.changePercent > 0 && <TrendUpIcon size={10} weight="bold" />}
        {item.changePercent < 0 && <TrendDownIcon size={10} weight="bold" />}
        {rateText(item.changePercent)}%
      </span>
    </span>
  )
}

/**
 * 하단 고정 티커 바(#41-A) — S&P500·필라델피아 반도체·VIX 등을 좌→우 무한
 * 스크롤로 노출한다. 목록을 두 벌 이어붙여 CSS 애니메이션으로 이음매 없이
 * 순환시키고(-50% 지점에서 루프), prefers-reduced-motion 사용자는 애니메이션을
 * 끈다. 키프레임은 컴포넌트 스코프 <style> 로 self-contained 하게 정의한다
 * (components/ui/chart.tsx 와 동일한 인라인 스타일 태그 패턴).
 */
export function MarketTicker() {
  return (
    <div className="overflow-hidden border-t border-border bg-card py-1.5" aria-label="시장 티커">
      <style
        dangerouslySetInnerHTML={{
          __html: `
@keyframes brokerage-ticker-scroll {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}
.brokerage-ticker-track {
  animation: brokerage-ticker-scroll 32s linear infinite;
}
@media (prefers-reduced-motion: reduce) {
  .brokerage-ticker-track {
    animation: none;
  }
}
`,
        }}
      />
      <div className="flex w-max brokerage-ticker-track">
        {[...TICKER_ITEMS, ...TICKER_ITEMS].map((item, i) => (
          <TickerEntry key={`${item.id}-${i}`} item={item} />
        ))}
      </div>
    </div>
  )
}

"use client"

import { useMemo, useState } from "react"
import { SparkleIcon } from "@phosphor-icons/react/dist/ssr"

import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { formatWon } from "@/lib/finance/format-won"
import { rateColor, rateText } from "@/lib/finance/rate"
import {
  SCREENER_MARKET_FILTERS,
  SCREENER_SORT_TABS,
  SCREENER_STOCKS,
  type ScreenerMarketFilter,
  type ScreenerSortKey,
  type ScreenerStock,
} from "../_data/screener"

/** 로고 이니셜 도형 배경(칩과 동일하게 chart 토큰을 순환 사용 — 하드코딩 색 없음) */
const LOGO_COLORS = ["bg-chart-1", "bg-chart-2", "bg-chart-3", "bg-chart-4", "bg-chart-5"]

function logoColorFor(symbol: string): string {
  let hash = 0
  for (let i = 0; i < symbol.length; i++) hash = (hash * 31 + symbol.charCodeAt(i)) % LOGO_COLORS.length
  return LOGO_COLORS[hash]
}

function sortStocks(stocks: ScreenerStock[], sort: ScreenerSortKey): ScreenerStock[] {
  const sorted = [...stocks]
  switch (sort) {
    case "tradingValue":
      return sorted.sort((a, b) => b.tradingValue - a.tradingValue)
    case "volume":
      return sorted.sort((a, b) => b.volume - a.volume)
    case "gainers":
      return sorted.sort((a, b) => b.changePercent - a.changePercent)
    case "losers":
      return sorted.sort((a, b) => a.changePercent - b.changePercent)
    default:
      return sorted
  }
}

export interface ScreenerTableProps {
  /** 스크리너 데이터 — 생략 시 내장 가상 종목(_data/screener.ts) 사용 */
  data?: ScreenerStock[]
  /** 행 클릭 시 선택된 종목을 부모로 전달(종목 상세 패널 연동용) */
  onSelect?: (stock: ScreenerStock) => void
  /** 선택된 종목 심볼 — 지정 시 해당 행을 강조(제어형), 생략 시 컴포넌트가 내부 상태로 관리 */
  selectedSymbol?: string
}

/**
 * 실시간 랭킹 스크리너 테이블 (#41 B영역).
 * 필터칩(전체/국내/해외) + 정렬 탭(거래대금·거래량·급상승·급락) + 순위/종목/시세 테이블.
 */
export function ScreenerTable({ data, onSelect, selectedSymbol }: Readonly<ScreenerTableProps>) {
  const [market, setMarket] = useState<ScreenerMarketFilter>("all")
  const [sort, setSort] = useState<ScreenerSortKey>("tradingValue")
  const [internalSelected, setInternalSelected] = useState<string | undefined>(undefined)

  const activeSelected = selectedSymbol ?? internalSelected
  const source = data ?? SCREENER_STOCKS

  const rows = useMemo(() => {
    const filtered = market === "all" ? source : source.filter((s) => s.market === market)
    return sortStocks(filtered, sort)
  }, [source, market, sort])

  function handleSelect(stock: ScreenerStock) {
    setInternalSelected(stock.symbol)
    onSelect?.(stock)
  }

  return (
    <div className="flex w-full flex-col gap-3">
      <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex flex-wrap items-center gap-1.5">
          {SCREENER_MARKET_FILTERS.map((f) => (
            <button
              key={f.key}
              type="button"
              aria-pressed={market === f.key}
              onClick={() => setMarket(f.key)}
              className={cn(
                "inline-flex shrink-0 items-center rounded-full border px-3 py-1 text-[12px] font-medium transition-colors",
                market === f.key
                  ? "border-transparent bg-primary text-primary-foreground"
                  : "border-border bg-card text-foreground hover:bg-accent",
              )}
            >
              {f.label}
            </button>
          ))}
        </div>

        <Tabs value={sort} onValueChange={(v) => setSort(v as ScreenerSortKey)}>
          <TabsList>
            {SCREENER_SORT_TABS.map((t) => (
              <TabsTrigger key={t.key} value={t.key}>
                {t.label}
              </TabsTrigger>
            ))}
          </TabsList>
        </Tabs>
      </div>

      <Table>
        <TableHeader>
          <TableRow>
            <TableHead className="w-10">순위</TableHead>
            <TableHead>종목</TableHead>
            <TableHead className="text-right">현재가</TableHead>
            <TableHead className="text-right">등락률</TableHead>
            <TableHead className="hidden text-right sm:table-cell">거래대금</TableHead>
            <TableHead className="hidden text-right md:table-cell">시가총액</TableHead>
            <TableHead className="hidden w-32 md:table-cell">거래비율</TableHead>
            <TableHead className="hidden lg:table-cell">산업</TableHead>
            <TableHead className="hidden lg:table-cell">AI 요약</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((stock, index) => (
            <TableRow
              key={stock.symbol}
              onClick={() => handleSelect(stock)}
              data-state={activeSelected === stock.symbol ? "selected" : undefined}
              className="cursor-pointer"
            >
              <TableCell className="tabular-nums text-muted-foreground">{index + 1}</TableCell>
              <TableCell>
                <div className="flex items-center gap-2">
                  <span
                    className={cn(
                      "flex size-8 shrink-0 items-center justify-center rounded-lg text-xs font-bold text-primary-foreground",
                      logoColorFor(stock.symbol),
                    )}
                    aria-hidden="true"
                  >
                    {stock.logoInitial}
                  </span>
                  <div className="flex flex-col">
                    <span className="text-sm font-medium">{stock.name}</span>
                    <span className="text-[10px] text-muted-foreground">
                      {stock.symbol} · {stock.market === "domestic" ? "국내" : "해외"}
                    </span>
                  </div>
                </div>
              </TableCell>
              <TableCell className="text-right tabular-nums">
                {stock.price.toLocaleString()}
                {stock.market === "domestic" ? "원" : ""}
              </TableCell>
              <TableCell className={cn("text-right font-semibold tabular-nums", rateColor(stock.changePercent))}>
                {rateText(stock.changePercent)}%
              </TableCell>
              <TableCell className="hidden text-right tabular-nums sm:table-cell">
                {formatWon(stock.tradingValue)}
              </TableCell>
              <TableCell className="hidden text-right tabular-nums md:table-cell">
                {formatWon(stock.marketCap)}
              </TableCell>
              <TableCell className="hidden md:table-cell">
                <BuyRatioBar buyRatio={stock.buyRatio} />
              </TableCell>
              <TableCell className="hidden lg:table-cell">
                <Badge variant="outline" className="text-[10px]">
                  {stock.industry}
                </Badge>
              </TableCell>
              <TableCell className="hidden max-w-48 lg:table-cell">
                <Badge variant="secondary" className="max-w-full gap-1 text-[10px]">
                  <SparkleIcon size={10} className="shrink-0" />
                  <span className="truncate">{stock.aiSummary}</span>
                </Badge>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  )
}

/** 매수/매도 비율 양방향 바 — 매수=gain(적), 매도=loss(청) 시맨틱 토큰 */
function BuyRatioBar({ buyRatio }: Readonly<{ buyRatio: number }>) {
  const sellRatio = 100 - buyRatio
  return (
    <div className="flex flex-col gap-0.5">
      <div className="flex h-1.5 w-full overflow-hidden rounded-full bg-muted">
        <div className="h-full bg-gain" style={{ width: `${buyRatio}%` }} />
        <div className="h-full bg-loss" style={{ width: `${sellRatio}%` }} />
      </div>
      <div className="flex justify-between text-[10px] text-muted-foreground tabular-nums">
        <span className="text-gain">매수 {buyRatio}%</span>
        <span className="text-loss">매도 {sellRatio}%</span>
      </div>
    </div>
  )
}

"use client"

import { RobotIcon, ChatCircleTextIcon, HeartIcon } from "@phosphor-icons/react/dist/ssr"

import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { Badge } from "@/components/ui/badge"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { rateColor, rateText } from "@/lib/finance/rate"
import { cn } from "@/lib/utils"
import {
  buildStockDetail,
  type Candle,
  type CommunityPost,
  type StockDetailInput,
} from "@/app/templates/brokerage/_data/detail"

const CHART_WIDTH = 560
const CHART_HEIGHT = 200
const CHART_PAD_X = 8
const CHART_PAD_TOP = 12
const CHART_PAD_BOTTOM = 36
const VOLUME_HEIGHT = 28

/** 일봉 캔들스틱 차트 — 외부 차트 라이브러리 없이 순수 SVG로 시가/고가/저가/종가 + 거래량을 그린다. */
function CandlestickChart({ candles }: Readonly<{ candles: Candle[] }>) {
  if (candles.length === 0) return null

  const drawTop = CHART_PAD_TOP
  const drawBottom = CHART_HEIGHT - CHART_PAD_BOTTOM
  const drawH = drawBottom - drawTop
  const volumeTop = drawBottom + 8
  const volumeBottom = volumeTop + VOLUME_HEIGHT

  const high = Math.max(...candles.map((c) => c.high))
  const low = Math.min(...candles.map((c) => c.low))
  const range = high - low || 1
  const pad = range * 0.08
  const yMin = low - pad
  const yMax = high + pad

  const maxVolume = Math.max(...candles.map((c) => c.volume)) || 1

  const innerWidth = CHART_WIDTH - CHART_PAD_X * 2
  const step = innerWidth / candles.length
  const bodyWidth = Math.max(step * 0.6, 2)

  const toY = (v: number) => drawTop + drawH - ((v - yMin) / (yMax - yMin)) * drawH
  const toX = (i: number) => CHART_PAD_X + step * i + step / 2

  const firstCandle = candles[0]
  const lastCandle = candles[candles.length - 1]
  const xAxisLabels = [firstCandle, candles[Math.floor(candles.length / 2)], lastCandle]

  return (
    <svg
      viewBox={`0 0 ${CHART_WIDTH} ${CHART_HEIGHT}`}
      className="h-auto w-full"
      role="img"
      aria-label="일봉 캔들스틱 차트"
    >
      {[0.25, 0.5, 0.75].map((ratio) => (
        <line
          key={ratio}
          x1={CHART_PAD_X}
          x2={CHART_WIDTH - CHART_PAD_X}
          y1={drawTop + drawH * ratio}
          y2={drawTop + drawH * ratio}
          stroke="var(--border)"
          strokeWidth={1}
          strokeDasharray="2,3"
        />
      ))}

      {candles.map((candle, index) => {
        const isUp = candle.close >= candle.open
        const x = toX(index)
        const bodyTop = toY(Math.max(candle.open, candle.close))
        const bodyBottom = toY(Math.min(candle.open, candle.close))
        const bodyHeight = Math.max(bodyBottom - bodyTop, 1)
        const volH = (candle.volume / maxVolume) * VOLUME_HEIGHT

        return (
          <g key={candle.date} className={isUp ? "text-gain" : "text-loss"}>
            <line x1={x} x2={x} y1={toY(candle.high)} y2={toY(candle.low)} stroke="currentColor" strokeWidth={1} />
            <rect x={x - bodyWidth / 2} y={bodyTop} width={bodyWidth} height={bodyHeight} fill="currentColor" />
            <rect
              x={x - bodyWidth / 2}
              y={volumeBottom - volH}
              width={bodyWidth}
              height={volH}
              fill="currentColor"
              opacity={0.35}
            />
          </g>
        )
      })}

      <line x1={CHART_PAD_X} x2={CHART_WIDTH - CHART_PAD_X} y1={volumeBottom} y2={volumeBottom} stroke="var(--border)" strokeWidth={1} />

      {xAxisLabels.map((candle, i) => (
        <text
          key={`${candle.date}-${i}`}
          x={i === 0 ? CHART_PAD_X : i === xAxisLabels.length - 1 ? CHART_WIDTH - CHART_PAD_X : CHART_WIDTH / 2}
          y={CHART_HEIGHT - 4}
          fontSize={9}
          fill="var(--muted-foreground)"
          textAnchor={i === 0 ? "start" : i === xAxisLabels.length - 1 ? "end" : "middle"}
        >
          {candle.date.slice(5)}
        </text>
      ))}
    </svg>
  )
}

function CommunityFeed({ posts }: Readonly<{ posts: CommunityPost[] }>) {
  return (
    <ul className="flex flex-col divide-y divide-border">
      {posts.map((post) => (
        <li key={post.id} className="flex gap-3 py-3 first:pt-0 last:pb-0">
          <Avatar size="sm">
            <AvatarFallback aria-hidden>{post.nickname.slice(0, 2)}</AvatarFallback>
